head.script:
scwin.onpageload = function () {
    // 팝업에서 전달받은 프로젝트 데이터 처리
    scwin.initializeProjectData();

    // 초기값 설정
    dm_ui_state.set("isLoading", "false");
    dm_ui_state.set("loadingMessage", "");
    dm_ui_state.set("currentView", "repositories");
    dm_auth_status.set("needsLogin", "true");

    // 초기 스크롤 모드 설정 (저장소 목록 화면)
    scwin.setPopupScrollMode('hidden');

    // 프로젝트 데이터 초기화
    scwin.initializeProjectData();

    // 이벤트 핸들러 초기화
    scwin.initializeEventHandlers();

    // 통합 연결 상태 확인 (OAuth + Installation ID 체크)
    scwin.checkGitHubConnectionStatus();

};

// 프로젝트 데이터 초기화 함수
scwin.initializeProjectData = function () {
    try {
        // 팝업에서 전달받은 데이터 확인
        var popupData = $p.getParameter("project_param");
        if (popupData) {

            // 프로젝트 정보를 폼에 설정
            dm_github_form.set("projectId", popupData.projectId);

            // 현재 프로젝트 정보를 전역 변수에 저장
            scwin.currentProjectData = popupData;

        } else {
            dm_github_form.set("projectId", "default-project-id");
            scwin.currentProjectData = null;
        }
    } catch (e) {
        dm_github_form.set("projectId", "default-project-id");
        scwin.currentProjectData = null;
    }
};

// 이벤트 핸들러 초기화
scwin.initializeEventHandlers = function () {
    try {
        // 검색 키워드 입력 이벤트 핸들러 (실시간 검색)
        setTimeout(function () {
            var searchInput = document.querySelector('input[ref="data:dm_github_form.repoSearchKeyword"]');
            if (searchInput) {
                searchInput.addEventListener('input', function () {
                    var value = this.value;
                    setTimeout(function () {
                        scwin.filterRepositories(value);
                    }, 300); // 300ms 디바운스 적용
                });
            }
        }, 100);

    } catch (e) {
    }
};

// OAuth 성공 메시지 리스너 초기화
scwin.initializeOAuthMessageListener = function () {
    try {
        // postMessage 이벤트 리스너 추가
        window.addEventListener('message', function (event) {

            if (event.data && event.data.type === 'githubAuthSuccess') {
                // 성공 알림 표시
                if (typeof $c !== 'undefined' && $c.win && $c.win.alert) {
                    $c.win.alert("GitHub 연동이 성공적으로 완료되었습니다!\n\n사용자: @" + (event.data.data.username || ""));
                }

                // 인증 상태 다시 확인
                setTimeout(function () {
                    scwin.checkAuthenticationStatus();
                }, 1000);
            }
        });

    } catch (e) {
    }
};

// GitHub 인증 상태 확인 (AJAX 방식 - myPage.xml 패턴 참조)
scwin.checkAuthenticationStatus = function () {
    scwin.setLoading(true, "인증 상태 확인 중...");

    try {
        $.ajax({
            url: "/InsWebApp/github/auth/status.pwkjson",
            type: "GET",
            dataType: "json",
            success: function (result) {
                scwin.setLoading(false);

                if (result && result.authenticated === true) {
                    // 인증된 상태
                    dm_auth_status.set("isAuthenticated", "true");
                    dm_auth_status.set("username", result.user ? result.user.login || "" : "");
                    dm_auth_status.set("avatarUrl", result.user ? result.user.avatar_url || "" : "");
                    dm_auth_status.set("hasGitHubApp", result.hasSelectedRepo ? "true" : "false");
                    dm_auth_status.set("needsLogin", "false");

                    scwin.showAuthenticatedUI();
                    // 기존 저장소가 있는지 확인하고 바로 브랜치 관리 화면으로 이동
                    scwin.checkCurrentRepository();
                } else {
                    // 인증되지 않은 상태
                    scwin.showLoginRequiredUI();
                }
            },
            error: function (xhr, status, error) {
                scwin.setLoading(false);
                scwin.showLoginRequiredUI();
            }
        });
    } catch (e) {
        scwin.setLoading(false);
        scwin.showLoginRequiredUI();
    }
};

// GitHub App 설치 필요 상태 처리
scwin.handleAppInstallRequired = function(result) {

    // 사용자 정보 표시
    if (result.user) {
        dm_auth_status.set("isAuthenticated", "true");
        dm_auth_status.set("username", result.user.login || "");
        dm_auth_status.set("avatarUrl", result.user.avatar_url || "");
        dm_auth_status.set("needsLogin", "false");
    }

    // GitHub App 설치 필요 상태로 설정
    dm_auth_status.set("hasGitHubApp", "false");

    // 자동으로 GitHub App 설치 팝업 열기
    scwin.openGitHubAppInstallPopup();
};

// 완전 연동 상태 처리
scwin.handleFullyConnected = function(result) {

    // 모든 인증 정보 설정
    dm_auth_status.set("isAuthenticated", "true");
    dm_auth_status.set("needsLogin", "false");
    dm_auth_status.set("hasGitHubApp", "true");

    if (result.user) {
        dm_auth_status.set("username", result.user.login || "");
        dm_auth_status.set("avatarUrl", result.user.avatar_url || "");
    }

    // 저장소 선택 섹션 표시
    scwin.showRepositorySelectionSection();

    // 기존 저장소 연결 상태 확인
    scwin.checkCurrentRepository();
};

// GitHub App 설치 팝업 열기
scwin.openGitHubAppInstallPopup = function() {
    try {
        const baseUrl = window.location.protocol + "//" + window.location.host;
        const installUrl = baseUrl + "/InsWebApp/github/app/install";

        // 설치 안내 메시지 표시
        const confirmMessage = "GitHub 저장소에 접근하려면 GitHub App을 설치해야 합니다.\n\n" +
                             "확인을 누르면 GitHub App 설치 페이지가 열립니다.\n" +
                             "설치 완료 후 이 창으로 다시 돌아와주세요.";

        if (confirm(confirmMessage)) {
            // GitHub App 설치 팝업 열기
            const installWindow = window.open(
                installUrl,
                'github_app_install_popup',
                'width=900,height=700,scrollbars=yes,resizable=yes,toolbar=no,menubar=no,location=no,status=no'
            );

            if (installWindow) {
                // 설치 완료 감지를 위한 주기적 체크 시작
                scwin.startInstallationCheckLoop();

                // 설치 안내 UI 표시
                scwin.showAppInstallPendingUI();
            } else {
                $c.win.alert("팝업이 차단되었습니다. 팝업 차단을 해제하고 다시 시도해주세요.");
            }
        }
    } catch (error) {
        $c.win.alert("GitHub App 설치 페이지를 열 수 없습니다: " + error.message);
    }
};

// 설치 완료 확인 루프 시작
scwin.startInstallationCheckLoop = function() {

    // 기존 체크 루프가 있다면 정리
    if (scwin.installationCheckInterval) {
        clearInterval(scwin.installationCheckInterval);
    }

    // 5초마다 설치 상태 확인
    scwin.installationCheckInterval = setInterval(function() {
        $.ajax({
            url: "/InsWebApp/github/connection/status.pwkjson",
            type: "GET",
            dataType: "json",
            success: function(result) {
                if (result && result.status === "fully_connected") {
                    // 체크 루프 정리
                    clearInterval(scwin.installationCheckInterval);
                    scwin.installationCheckInterval = null;

                    // 완전 연동 상태 처리
                    scwin.handleFullyConnected(result);

                    // 성공 메시지
                    $c.win.alert("GitHub App 설치가 완료되었습니다!");
                }
            },
            error: function(xhr, status, error) {
            }
        });
    }, 5000); // 5초 간격

    // 5분 후 자동 정리 (타임아웃)
    setTimeout(function() {
        if (scwin.installationCheckInterval) {
            clearInterval(scwin.installationCheckInterval);
            scwin.installationCheckInterval = null;
        }
    }, 300000); // 5분
};

// App 설치 대기 UI 표시
scwin.showAppInstallPendingUI = function() {
    // 새로운 섹션 관리 함수 사용
    scwin.showAppInstallPendingSection();
};

// 모든 섹션 숨기기 (완전 분리)
scwin.hideAllSections = function() {
    try {
        // 1. 로딩 오버레이 숨기기
        scwin.setLoading(false);

        // 2. 로그인 필요 섹션 숨기기
        var loginSection = $p.getComponentById("login_required_section");
        if (loginSection) {
            loginSection.addClass("hidden");
            loginSection.setStyle("display", "none");
        }

        // 3. 메인 GitHub 컨텐츠 숨기기
        var mainContent = $p.getComponentById("github_main_content");
        if (mainContent) {
            mainContent.setStyle("display", "none");
        }

        // 4. 저장소 관련 섹션들 숨기기
        var repoLoadingSection = $p.getComponentById("repo_loading_section");
        if (repoLoadingSection) {
            repoLoadingSection.setStyle("display", "none");
        }

        var repoEmptySection = $p.getComponentById("repo_empty_section");
        if (repoEmptySection) {
            repoEmptySection.setStyle("display", "none");
        }

        var repoCardsContainer = $p.getComponentById("repo_cards_container");
        if (repoCardsContainer) {
            repoCardsContainer.setStyle("display", "none");
        }

        // 5. 브랜치 관리 섹션 제거 (동적 생성된 요소)
        var branchSection = $p.getComponentById("branch_management_section");
        if (branchSection) {
            branchSection.remove();
        }
    } catch (error) {
    }
};

// 로그인 필요 섹션만 표시
scwin.showLoginRequiredSection = function() {
    // 모든 섹션 숨기기
    scwin.hideAllSections();

    // 로그인 섹션만 표시
    var loginSection = $p.getComponentById("login_required_section");
    if (loginSection) {
        loginSection.removeClass("hidden");
        loginSection.setStyle("display", "block");
    }

    // 상태 업데이트
    dm_auth_status.set("needsLogin", "true");
    dm_ui_state.set("currentView", "login");
};

// 저장소 선택 섹션 표시
scwin.showRepositorySelectionSection = function() {

    // 모든 섹션 숨기기
    scwin.hideAllSections();

    // 메인 컨텐츠와 저장소 카드 컨테이너 표시
    var mainContent = $p.getComponentById("github_main_content");
    if (mainContent) {
        mainContent.setStyle("display", "block");
    }

    var repoCardsContainer = $p.getComponentById("repo_cards_container");
    if (repoCardsContainer) {
        repoCardsContainer.setStyle("display", "block");
    }

    // 상태 업데이트
    dm_ui_state.set("currentView", "repositories");
    dm_auth_status.set("needsLogin", "false");
};

// 브랜치 관리 섹션 표시
scwin.showBranchManagementSection = function(repositoryData) {

    // 모든 섹션 숨기기
    scwin.hideAllSections();

    // 메인 컨텐츠 표시
    var mainContent = $p.getComponentById("github_main_content");
    if (mainContent) {
        mainContent.setStyle("display", "block");
    }

    // 브랜치 관리 섹션 생성 (기존 로직 활용)
    scwin.createBranchManagementUI(repositoryData);

    // 상태 업데이트
    dm_ui_state.set("currentView", "branches");
    dm_auth_status.set("needsLogin", "false");
};

// App 설치 대기 섹션 표시
scwin.showAppInstallPendingSection = function() {

    // 모든 섹션 숨기기
    scwin.hideAllSections();

    // 로딩 UI로 설치 대기 상태 표시
    scwin.setLoading(true, "GitHub App 설치를 완료해주세요.\n\n설치 완료 후 자동으로 연결됩니다.");
};

// 통합 연결 상태 체크 (섹션 완전 분리 적용)
scwin.checkGitHubConnectionStatus = function() {
    // 임시 로딩 표시 (섹션 숨기지 않음)
    scwin.setLoading(true, "연결 상태 확인 중...");

    $.ajax({
        url: "/InsWebApp/github/connection/status.pwkjson",
        type: "GET",
        dataType: "json",
        success: function(result) {
            if (result && result.status) {
                switch (result.status) {
                    case "oauth_required":
                        scwin.showLoginRequiredSection();
                        break;

                    case "app_install_required":
                        scwin.handleAppInstallRequired(result);
                        break;

                    case "fully_connected":
                        scwin.handleFullyConnected(result);
                        break;

                    default:
                        scwin.showLoginRequiredSection();
                }
            } else {
                scwin.showLoginRequiredSection();
            }
        },
        error: function(xhr, status, error) {
            scwin.showLoginRequiredSection();
        }
    });
};

// 인증 상태 확인 완료 핸들러
scwin.checkAuthenticationStatus_submitdone = function (e) {
    scwin.setLoading(false);

    var result = null;
    if (e.responseJSON) {
        result = e.responseJSON;
    } else if (e.responseText) {
        result = JSON.parse(e.responseText);
    }

    if (result && result.authenticated === true) {
        // 인증된 상태
        dm_auth_status.set("isAuthenticated", "true");
        dm_auth_status.set("username", result.user ? result.user.login || "" : "");
        dm_auth_status.set("avatarUrl", result.user ? result.user.avatar_url || "" : "");
        dm_auth_status.set("hasGitHubApp", result.hasSelectedRepo ? "true" : "false");
        dm_auth_status.set("needsLogin", "false");

        scwin.showAuthenticatedUI();
        scwin.loadConnectedRepositories();
    } else {
        // 인증되지 않은 상태
        scwin.showLoginRequiredUI();
    }

};

// 인증 상태 확인 실패 핸들러
scwin.checkAuthenticationStatus_submiterror = function (e) {
    scwin.setLoading(false);
    scwin.showLoginRequiredUI();
};

// GitHub 인증 상태 확인 완료 핸들러
scwin.checkAuthStatus_submit_done = function (e) {
    scwin.setLoading(false);

    var result = null;
    try {
        if (e.responseJSON) {
            result = e.responseJSON;
        } else if (e.responseText) {
            result = JSON.parse(e.responseText);
        }
    } catch (parseError) {
        result = null;
    }

    if (result && result.authenticated === true) {
        // 인증된 상태
        dm_auth_status.set("isAuthenticated", "true");
        dm_auth_status.set("username", result.user ? result.user.login || "" : "");
        dm_auth_status.set("avatarUrl", result.user ? result.user.avatar_url || "" : "");
        dm_auth_status.set("hasGitHubApp", result.hasSelectedRepo ? "true" : "false");
        dm_auth_status.set("needsLogin", "false");

        scwin.showAuthenticatedUI();
        scwin.loadConnectedRepositories();
    } else {
        // 인증되지 않은 상태
        scwin.showLoginRequiredUI();
    }
};

// GitHub 인증 상태 확인 실패 핸들러
scwin.checkAuthStatus_submiterror = function (e) {
    scwin.setLoading(false);
    scwin.showLoginRequiredUI();
};

/**
 * GitHub 로그인 팝업을 열고, 콜백 메시지를 비동기적으로 처리
 */
scwin.redirectToGitHubLogin = function () {

    try {
        // OAuth URL 생성
        const baseUrl = window.location.protocol + "//" + window.location.host;
        let githubAuthStartUrl = baseUrl + "/InsWebApp/github/auth/start";

        // 현재 프로젝트 데이터에서 사용자 ID와 프로젝트 ID 가져오기
        const params = [];
        if (scwin.currentProjectData) {
            if (scwin.currentProjectData.projectId) {
                params.push("projectId=" + encodeURIComponent(scwin.currentProjectData.projectId));
            }
        }

        // URL 파라미터 추가
        if (params.length > 0) {
            githubAuthStartUrl += "?" + params.join("&");
        }

        // 팝업에 전달할 데이터
        const popupData = {
            authUrl: githubAuthStartUrl,
            projectData: scwin.currentProjectData,
            callbackFn: async function (result) {

                if (result && result.status === 'success') {
                    $c.win.alert("GitHub 계정이 성공적으로 연동되었습니다.");

                    try {
                        // 팝업 크기 확대 (로그인 성공 후)

                        // 인증 성공 처리
                        dm_auth_status.set("isAuthenticated", "true");
                        dm_auth_status.set("needsLogin", "false");

                        if (result.data && result.data.user) {
                            dm_auth_status.set("username", result.data.user.login || "");
                            dm_auth_status.set("avatarUrl", result.data.user.avatar_url || "");
                        }
                        dm_auth_status.set("hasGitHubApp", result.data && result.data.hasSelectedRepo ? "true" : "false");

                        // UI 업데이트
                        scwin.showAuthenticatedUI();

                        // 인증 상태 안정화를 위한 대기
                        await scwin.waitForAuthStabilization();

                        // 현재 저장소 확인
                        await scwin.checkCurrentRepositoryAsync();

                    } catch (error) {
                        // 에러 발생 시 저장소 선택 화면으로 이동
                        try {
                            await scwin.showRepositorySelectionViewAsync();
                        } catch (fallbackError) {
                            // 최후의 수단으로 기존 동기 방식 사용
                            scwin.showRepositorySelectionView();
                        }
                    }

                } else {
                    const errorMessage = result && result.data ? result.data.message : "알 수 없는 오류";
                    $c.win.alert("GitHub 계정 연동에 실패했습니다: " + errorMessage);
                }
            }
        };

        // 전역 콜백 함수 등록
        window.githubAuthCallback = popupData.callbackFn;

        // postMessage 이벤트 리스너 등록
        const messageListener = function (event) {

            // 보안을 위해 origin 확인
            if (event.origin !== window.location.origin) {
                return;
            }

            if (event.data && event.data.type === 'githubAuthResult') {

                // 이벤트 리스너 제거
                window.removeEventListener('message', messageListener);

                // 콜백 함수 호출
                if (typeof popupData.callbackFn === 'function') {
                    popupData.callbackFn(event.data.result);
                }
            }
        };

        window.addEventListener('message', messageListener);


        // WebSquare 팝업 대신 직접 브라우저 팝업 사용
        const authWindow = window.open(
            githubAuthStartUrl,
            'github_oauth_popup',
            'width=800,height=650,scrollbars=yes,resizable=yes,toolbar=no,menubar=no,location=no,status=no'
        );

        if (authWindow) {
            // 팝업이 닫힐 때까지 주기적으로 확인
            const checkClosed = setInterval(() => {
                if (authWindow.closed) {
                    clearInterval(checkClosed);

                    // 이벤트 리스너 정리
                    window.removeEventListener('message', messageListener);

                    // 인증 상태 재확인 (postMessage 실패 시 백업)
                    setTimeout(() => {
                        scwin.checkAuthenticationStatus();
                    }, 1000);
                }
            }, 1000);

            // 5분 후 자동 정리
            setTimeout(() => {
                clearInterval(checkClosed);
                window.removeEventListener('message', messageListener);
                if (authWindow && !authWindow.closed) {
                    authWindow.close();
                }
            }, 300000);
        } else {
            window.removeEventListener('message', messageListener);
            $c.win.alert("팝업이 차단되었습니다. 브라우저 설정에서 팝업 차단을 해제한 후 다시 시도해주세요.");
        }

    } catch (e) {
        $c.win.alert("GitHub 인증을 시작할 수 없습니다: " + e.message);
    }
};


// 로그인 필요 UI 표시
scwin.showLoginRequiredUI = function () {

    // 새로운 섹션 관리 함수 사용
    scwin.showLoginRequiredSection();
};

// 로그인 필요 섹션 동적 생성
scwin.createLoginRequiredSection = function () {
    try {
        // 기존 로그인 섹션이 있으면 제거
        var existingLoginSection = $p.getComponentById("login_required_section");
        if (existingLoginSection) {
            existingLoginSection.remove();
        }

        // 메인 컨테이너 찾기
        var container = $p.getComponentById("github_main_content");

        // 로그인 필요 섹션 그룹 생성
        var loginSection = $p.dynamicCreate(
            "login_required_section",
            "group",
            {
