// 인증된 UI 표시
scwin.showAuthenticatedUI = function () {

    // 팝업 크기 확대 (백엔드에서 인증 상태 확인 후)

    // 상태 업데이트
    dm_auth_status.set("needsLogin", "false");
    dm_auth_status.set("isAuthenticated", "true");

    // 저장소 선택 섹션 표시
    scwin.showRepositorySelectionSection();
};

// GitHub 레포지토리 목록 로드 (프론트엔드에서 직접 GitHub API 호출)
scwin.loadConnectedRepositories = function () {
    if (dm_auth_status.get("needsLogin") === "true") {
        return;
    }

    scwin.setLoading(true, "GitHub 레포지토리 목록 로딩 중...");

    // 레포지토리 로딩 상태 표시
    scwin.showRepositoryLoadingState();

    // 먼저 세션에서 GitHub 토큰 가져오기
    $.ajax({
        url: "/InsWebApp/github/auth/status.pwkjson",
        type: "GET",
        dataType: "json",
        success: function (authResult) {
            if (!authResult.authenticated) {
                scwin.setLoading(false);
                scwin.showLoginRequiredUI();
                return;
            }

            // GitHub API 직접 호출 (CORS 문제로 프록시 방식 사용)
            $.ajax({
                url: "/InsWebApp/github/api/repositories.pwkjson",
                type: "GET",
                dataType: "json",
                data: {
                    sort: "updated",
                    per_page: 100,
                    affiliation: "owner,collaborator"
                },
                success: function (repositories) {
                    scwin.setLoading(false);

                    // DataList 초기화
                    dlt_GitHubRepositoryVoList.removeAll();

                    // 문자열을 JSON으로 파싱
                    try {
                        if (typeof repositories === 'string') {
                            repositories = JSON.parse(repositories);
                        }
                    } catch (e) {
                        scwin.showEmptyRepositoryState();
                        return;
                    }

                    // 레포지토리 데이터 검증
                    if (!Array.isArray(repositories)) {
                        scwin.showEmptyRepositoryState();
                        return;
                    }

                    // 레포지토리 데이터를 직접 카드 형태로 출력
                    scwin.renderRepositoryCards(repositories);

                    // 레포지토리 개수 표시 업데이트
                    scwin.updateRepositoryCount(repositories.length);

                    // 저장소 목록 화면에서는 스크롤 숨김
                    scwin.setPopupScrollMode('hidden');
                },
                error: function (xhr, status, error) {
                    scwin.setLoading(false);

                    scwin.showEmptyRepositoryState();

                    if (xhr.status === 401) {
                        $c.win.alert("GitHub 인증이 만료되었습니다. 다시 로그인해주세요.");
                        scwin.showLoginRequiredUI();
                    } else {
                        $c.win.alert("GitHub에서 레포지토리 목록을 불러올 수 없습니다.\n오류: " + (xhr.responseText || error));
                    }
                }
            });
        },
        error: function (xhr, status, error) {
            scwin.setLoading(false);
            scwin.showLoginRequiredUI();
        }
    });
};

// 레포지토리 표시 업데이트
scwin.updateRepositoryDisplay = function () {
    try {
        var totalRepos = dlt_GitHubRepositoryVoList.getTotalRow();
        var privateRepos = 0;
        var publicRepos = 0;

        // 상태 카운트 계산
        for (var i = 0; i < totalRepos; i++) {
            var isPrivate = dlt_GitHubRepositoryVoList.getCellData(i, "isPrivate");
            if (isPrivate && isPrivate.indexOf("Private") !== -1) {
                privateRepos++;
            } else {
                publicRepos++;
            }
        }

        // 헤더 정보 업데이트
        var countText = "총 " + totalRepos + "개 레포지토리 (" +
            publicRepos + "개 공개, " + privateRepos + "개 비공개)";

        var countElement = document.getElementById("repo-count-info");
        if (countElement) {
            countElement.textContent = countText;
        }

        // 카드 형태로 레포지토리 표시
        scwin.renderRepositoryCards();

    } catch (e) {
    }
};

// 레포지토리 카드 렌더링 (웹스퀘어 방식)
scwin.renderRepositoryCards = function (repositories) {
    try {
        // 카드 컨테이너 찾기
        var cardsContainer = $p.getComponentById("repo_cards_container");
        if (!cardsContainer) {
            return;
        }

        // 컨테이너 스크롤 스타일 적용 (웹스퀘어 방식)
        try {
            var containerComponent = $p.getComponentById("repo_cards_container");
            if (containerComponent) {
                // JavaScript 방식으로 스타일 적용
                var realDomElement = document.getElementById(containerComponent.id);
                if (realDomElement) {

                    // 강제로 display: grid 적용
                    realDomElement.style.display = "grid";
                    realDomElement.style.maxHeight = "350px";
                    realDomElement.style.overflowY = "auto";
                    realDomElement.style.padding = "10px";
                    realDomElement.style.visibility = "visible";


                    // 비동기 스타일 재적용 함수
                    const recheckAndApplyStyles = async () => {
                        // 웹스퀘어 렌더링 완료 대기
                        await new Promise(resolve => setTimeout(resolve, 100));


                        // 웹스퀘어가 덮어썼다면 다시 적용
                        if (realDomElement.style.display !== "grid") {
                            realDomElement.style.display = "grid";
                            realDomElement.style.setProperty("display", "grid", "important");

                            // 추가 확인 (한 번 더 대기 후 최종 확인)
                            await new Promise(resolve => setTimeout(resolve, 50));
                        } else {
                        }
                    };

                    // 비동기 함수 실행
                } else {
                }
            } else {
            }
        } catch (e) {
        }

        // 로딩 상태 숨기기
        var loadingSection = $p.getComponentById("repo_loading_section");
        if (loadingSection) {
            loadingSection.hide();
        }

        if (!repositories || repositories.length === 0) {
            // 빈 상태 표시
            var emptySection = $p.getComponentById("repo_empty_section");
            if (emptySection) {
                emptySection.show();
            }
            cardsContainer.hide();
            return;
        }

        // 빈 상태 숨기기
        var emptySection = $p.getComponentById("repo_empty_section");
        if (emptySection) {
            emptySection.hide();
        }

        // 기존 카드 제거
        scwin.clearRepositoryCards();

        // 주의사항 문구 동적 생성 (카드 컨테이너의 부모에 생성)
        var parentContainer = cardsContainer.getParent();
        scwin.createAdminConnectionWarning(parentContainer);

        // 각 레포지토리를 카드로 렌더링
        for (var i = 0; i < repositories.length; i++) {
            var repo = repositories[i];
            scwin.createRepositoryCard(repo, i, cardsContainer);
        }

        // 카드 컨테이너 표시
        cardsContainer.show();

    } catch (e) {
    }
};

// 저장소 개수 업데이트
scwin.updateRepositoryCount = function (count) {
    try {
        var countElement = document.getElementById("repo-count-info");
        if (countElement) {
            countElement.textContent = "총 " + count + "개의 저장소";
        }
    } catch (e) {
    }
};

// 날짜 포맷팅 함수
scwin.formatDate = function (dateString) {
    try {
        if (!dateString) return "";
        var date = new Date(dateString);
        return date.toLocaleDateString('ko-KR');
    } catch (e) {
        return dateString;
    }
};

// 기존 카드 제거
scwin.clearRepositoryCards = function () {
    try {
        var cardsContainer = $p.getComponentById("repo_cards_container");
        if (cardsContainer) {
            // 자식 컴포넌트들을 모두 제거
            var children = cardsContainer.getChildren();
            for (var i = children.length - 1; i >= 0; i--) {
                children[i].remove();
            }
        }
    } catch (e) {
    }
};

// 관리자 연결 필요 주의사항 문구 동적 생성
