                className: "admin-connection-warning"
            },
            container
        );
        warningSpan.setValue("GitHub 저장소에 자동으로 팀원을 초대하려면, 해당 저장소의 관리자(Admin 권한)가 먼저 연결해야 합니다.");

    } catch (e) {
