// 저장소 목록으로 돌아가기
scwin.showRepositoryList = function () {

    try {
        // 1. 저장소 선택 섹션으로 완전 전환 (새로운 섹션 관리 함수 사용)
        scwin.showRepositorySelectionSection();

        // 2. 현재 저장소 정보 초기화
        scwin.currentRepository = null;
        dm_ui_state.set("selectedRepo", "");

        // 3. 저장소 데이터 새로 요청 (자동 갱신)
        scwin.loadConnectedRepositories();

        // 저장소 목록 화면에서는 스크롤 숨김
        scwin.setPopupScrollMode('hidden');

    } catch (e) {

        // 오류 시 기본 저장소 선택 화면으로라도 전환
        try {
            scwin.showRepositorySelectionSection();
        } catch (fallbackError) {
        }
    }
};

// 브랜치 목록 로드
scwin.loadBranches = function (repoInfo) {
    try {

        // 로딩 상태 표시
        scwin.showBranchLoadingState();

        // 브랜치 조회 파라미터 설정

        var projectId = scwin.getCurrentProjectId();

        dm_branch_params.set("owner", repoInfo.owner);
        dm_branch_params.set("repo", repoInfo.name);
        dm_branch_params.set("projectId", projectId);

        // 파라미터 확인

        // 서브미션 실행
        $p.executeSubmission("sbm_loadBranches");

    } catch (e) {
        scwin.showBranchErrorState("브랜치 목록을 불러오는 중 오류가 발생했습니다.");
    }
};

