        setTimeout(resolve, 1000);
    });
};

// 현재 저장소 확인 (async 버전)
scwin.checkCurrentRepositoryAsync = function() {
    return new Promise((resolve, reject) => {

        // 임시 콜백 함수들을 저장
        const originalSubmitdone = scwin.sbm_getCurrentRepository_submitdone;
        const originalSubmiterror = scwin.sbm_getCurrentRepository_submiterror;

        scwin.sbm_getCurrentRepository_submitdone = async function(e) {

            try {
                const response = e.responseJSON || e.response;

                if (response && response.success && response.repository) {
                    // 저장소가 있는 경우 - 원래 콜백 실행
                    originalSubmitdone.call(this, e);

                    // 콜백 복원
                    scwin.sbm_getCurrentRepository_submitdone = originalSubmitdone;
                    scwin.sbm_getCurrentRepository_submiterror = originalSubmiterror;

                    resolve(e);
                } else {
                    // 저장소가 없는 경우 - async 저장소 선택 화면 표시

                    // 콜백 복원
                    scwin.sbm_getCurrentRepository_submitdone = originalSubmitdone;
                    scwin.sbm_getCurrentRepository_submiterror = originalSubmiterror;

                    try {
                        await scwin.showRepositorySelectionViewAsync();
                        resolve(e);
                    } catch (error) {
                        reject(error);
                    }
                }
            } catch (err) {

                // 콜백 복원
                scwin.sbm_getCurrentRepository_submitdone = originalSubmitdone;
                scwin.sbm_getCurrentRepository_submiterror = originalSubmiterror;

                reject(err);
            }
        };

        // 에러 콜백 오버라이드
        scwin.sbm_getCurrentRepository_submiterror = async function(e) {

            // 콜백 복원
            scwin.sbm_getCurrentRepository_submitdone = originalSubmitdone;
            scwin.sbm_getCurrentRepository_submiterror = originalSubmiterror;

            // 실패 시 저장소 선택 화면 표시
            try {
                await scwin.showRepositorySelectionViewAsync();
                reject(e);
            } catch (error) {
                reject(e);
            }
        };

        try {
            // 현재 저장소 조회 서브미션 실행
            $p.executeSubmission("sbm_getCurrentRepository");
        } catch (error) {
            // 콜백 복원
            scwin.sbm_getCurrentRepository_submitdone = originalSubmitdone;
            scwin.sbm_getCurrentRepository_submiterror = originalSubmiterror;
            reject(error);
        }
    });
};

// 저장소 선택 화면 표시 (async 버전)
scwin.showRepositorySelectionViewAsync = async function() {

    try {
        // 브랜치 관리 섹션 숨기기
        const branchSection = $p.getComponentById("branch_management_section");
        if (branchSection) {
            branchSection.remove();
        }

        // 저장소 카드 컨테이너 표시
        const cardsContainer = $p.getComponentById("repo_cards_container");
        if (cardsContainer) {
            cardsContainer.show();
        }

        // 저장소 목록 로드
        await scwin.loadConnectedRepositoriesAsync();


    } catch (error) {
        throw error;
    }
};

// 레포지토리 목록 로드 (async 버전)
scwin.loadConnectedRepositoriesAsync = function() {
    return new Promise((resolve, reject) => {

        if (dm_auth_status.get("needsLogin") === "true") {
            reject(new Error("인증되지 않은 상태"));
            return;
        }

        scwin.setLoading(true, "GitHub 레포지토리 목록 로딩 중...");
        scwin.showRepositoryLoadingState();

        // 먼저 세션에서 GitHub 토큰 가져오기
        $.ajax({
            url: "/InsWebApp/github/auth/status.pwkjson",
            type: "GET",
            dataType: "json",
            success: function (authResult) {
                if (!authResult.authenticated) {
                    scwin.setLoading(false);
                    scwin.showLoginRequiredUI();
                    reject(new Error("인증되지 않은 상태"));
                    return;
                }

                // GitHub API 호출
                $.ajax({
                    url: "/InsWebApp/github/api/repositories.pwkjson",
                    type: "GET",
                    dataType: "json",
                    data: {
                        sort: "updated",
                        per_page: 100,
                        affiliation: "owner,collaborator"
                    },
                    success: function (repositories) {
                        scwin.setLoading(false);

                        try {
                            // DataList 초기화
                            dlt_GitHubRepositoryVoList.removeAll();

                            // 문자열을 JSON으로 파싱
                            if (typeof repositories === 'string') {
                                repositories = JSON.parse(repositories);
                            }

                            // 배열인지 확인하고 처리
                            if (Array.isArray(repositories) && repositories.length > 0) {
                                scwin.renderRepositoryCards(repositories);
                                scwin.updateRepositoryCount(repositories.length);
                                resolve(repositories);
                            } else {
                                scwin.showEmptyRepositoryState();
                                resolve([]);
                            }
                        } catch (error) {
                            scwin.showEmptyRepositoryState();
                            reject(error);
                        }
                    },
                    error: function (xhr, status, error) {
                        scwin.setLoading(false);
                        scwin.showRepositoryLoadingError();
                        reject(new Error("GitHub API 호출 실패: " + error));
                    }
                });
            },
            error: function (xhr, status, error) {
                scwin.setLoading(false);
                scwin.showLoginRequiredUI();
                reject(new Error("인증 상태 확인 실패: " + error));
            }
        });
    });
};

// 현재 프로젝트에 연결된 저장소 확인
scwin.checkCurrentRepository = function () {
    try {

        // 프로젝트 정보가 있는지 확인
        if (!scwin.currentProjectData || !scwin.currentProjectData.projectId) {
            // 프로젝트 정보가 없어도 사용자 ID로 저장소 확인 가능
        }

        // 현재 저장소 조회 서브미션 실행
        $p.executeSubmission("sbm_getCurrentRepository");

    } catch (e) {
        // 오류 발생 시 기본 저장소 목록 표시
        scwin.showRepositorySelectionView();
    }
};

// 현재 저장소 조회 성공 콜백
scwin.sbm_getCurrentRepository_submitdone = function (e) {

    try {
        var response = e.responseJSON || e.response;

        if (response && response.success && response.repository) {
            var repository = response.repository;

            // 저장소 정보를 repoInfo 형태로 변환
            var repoInfo = {
                id: repository.githubRepositoryId,
                name: repository.repoName,
                owner: repository.repoOwner,
                default_branch: repository.defaultBranch || "main"
            };

            // 디버그 로그

            // 바로 브랜치 관리 화면으로 이동
            scwin.showBranchManagementView(repoInfo);

        } else {
            // 연결된 저장소가 없으면 저장소 선택 화면 표시
            scwin.showRepositorySelectionView();
        }
    } catch (err) {
        // 오류 발생 시 저장소 선택 화면 표시
        scwin.showRepositorySelectionView();
    }
};

// 현재 저장소 조회 실패 콜백
scwin.sbm_getCurrentRepository_submiterror = function (e) {
    // 실패 시 저장소 선택 화면 표시
    scwin.showRepositorySelectionView();
};


// 브랜치 삭제 성공 콜백
scwin.sbm_deleteBranch_submitdone = function (e) {

    try {
        var response = e.responseJSON || e.response;

        if (response && response.success) {
            $c.win.alert("성공: 브랜치 삭제 성공!");

            // 브랜치 목록 새로고침
            setTimeout(function() {
                if (scwin.currentRepository) {
                    scwin.loadBranches(scwin.currentRepository);
                }
            }, 1000);

        } else if (response && response.error_code === 'AUTH_EXPIRED') {
            // 토큰 만료 처리
            $c.win.confirm("GitHub 토큰이 만료되었습니다. 다시 로그인하시겠습니까?", function(result) {
                if (result) {
                    scwin.redirectToGitHubLogin();
                }
            });
        } else {
            $c.win.alert("실패: 브랜치 삭제 실패\n\n오류: " + (response?.error || "알 수 없는 오류"));
        }
    } catch (err) {
        $c.win.alert("실패: 브랜치 삭제 응답 처리 중 오류가 발생했습니다: " + err.message);
    }
};

// 브랜치 삭제 실패 콜백
scwin.sbm_deleteBranch_submiterror = function (e) {

    var errorMsg = "브랜치 삭제에 실패했습니다.";
    if (e.responseJSON && e.responseJSON.error) {
        errorMsg += "\n\n오류: " + e.responseJSON.error;
    } else if (e.responseText) {
        try {
            var parsed = JSON.parse(e.responseText);
            if (parsed.error) {
                errorMsg += "\n\n오류: " + parsed.error;
            }
        } catch (parseErr) {
            errorMsg += "\n\n원본 오류: " + e.responseText;
        }
    }

    $c.win.alert("실패: " + errorMsg);
};

// 저장소 선택 화면 표시 (기존 로직)
scwin.showRepositorySelectionView = function () {
    try {

        // 브랜치 관리 섹션 숨기기
        var branchSection = $p.getComponentById("branch_management_section");
        if (branchSection) {
            branchSection.remove();
        }

        // 저장소 카드 컨테이너 표시
        var cardsContainer = $p.getComponentById("repo_cards_container");
        if (cardsContainer) {
            cardsContainer.show();
        }

        // 저장소 목록 로드 - 동기 버전 사용
        scwin.loadConnectedRepositories();

    } catch (e) {
    }
};

// 히스토리 추가
scwin.addToHistory = function (action, repoName, branchName, result) {
    try {
        dlt_repo_history.insertRow(0);
        dlt_repo_history.setCellData(0, "action", action);
        dlt_repo_history.setCellData(0, "repoName", repoName || "");
        dlt_repo_history.setCellData(0, "branchName", branchName || "");
        dlt_repo_history.setCellData(0, "timestamp", new Date().toLocaleString());
        dlt_repo_history.setCellData(0, "result", result);

        // 최대 50개 히스토리 유지
        while (dlt_repo_history.getTotalRow() > 50) {
            dlt_repo_history.deleteRow(dlt_repo_history.getTotalRow() - 1);
        }

    } catch (e) {
    }
};

