// 브랜치 생성
scwin.createBranch = function () {
    var branchName = dm_github_form.get("newBranchName");
    var sourceBranch = dm_github_form.get("sourceBranch");
    var currentRepo = dm_github_form.get("currentRepo");

    if (!branchName || !sourceBranch || !currentRepo) {
        $c.win.alert("브랜치명, 소스 브랜치, 레포지토리를 모두 선택해주세요.");
        return;
    }

    var parts = currentRepo.split("/");
    if (parts.length !== 2) {
        $c.win.alert("올바른 레포지토리가 선택되지 않았습니다.");
        return;
    }

    scwin.setLoading(true, "브랜치 생성 중...");

    var requestData = {
        owner: parts[0],
        repo: parts[1],
        branchName: branchName,
        sourceBranch: sourceBranch
    };

    try {
        $c.sbm.execute(sbm_createBranch, requestData).then(function (e) {
            scwin.setLoading(false);

            $c.win.alert("브랜치 '" + branchName + "'가 성공적으로 생성되었습니다.");
            dm_github_form.set("newBranchName", "");

            // 브랜치 목록 새로고침
            scwin.loadBranches(parts[0], parts[1]);
            scwin.addToHistory("create_branch", parts[1], branchName, "성공");
        }).catch(function (e) {
            scwin.setLoading(false);
            var errorMsg = scwin.getErrorMessage(e);
            $c.win.alert("브랜치 생성에 실패했습니다.\n" + errorMsg);
            scwin.addToHistory("create_branch", parts[1], branchName, "실패");
        });
    } catch (e) {
        scwin.setLoading(false);
    }
};

// 브랜치 삭제
scwin.deleteBranch = function (branchName) {
    var currentRepo = dm_github_form.get("currentRepo");

    if (!branchName || !currentRepo) {
        $c.win.alert("삭제할 브랜치와 레포지토리를 선택해주세요.");
        return;
    }

    if (!$c.win.confirm("브랜치 '" + branchName + "'를 삭제하시겠습니까?\n\n이 작업은 되돌릴 수 없습니다.")) {
        return;
    }

    var parts = currentRepo.split("/");
    if (parts.length !== 2) {
        $c.win.alert("올바른 레포지토리가 선택되지 않았습니다.");
        return;
    }

    scwin.setLoading(true, "브랜치 삭제 중...");

    var requestData = {
        owner: parts[0],
        repo: parts[1],
        branchName: branchName
    };

    try {
        $c.sbm.execute(sbm_deleteBranch, requestData).then(function (e) {
            scwin.setLoading(false);

            $c.win.alert("브랜치 '" + branchName + "'가 성공적으로 삭제되었습니다.");

            // 브랜치 목록 새로고침
            scwin.loadBranches(parts[0], parts[1]);
            scwin.addToHistory("delete_branch", parts[1], branchName, "성공");
        }).catch(function (e) {
            scwin.setLoading(false);
            var errorMsg = scwin.getErrorMessage(e);
            $c.win.alert("브랜치 삭제에 실패했습니다.\n" + errorMsg);
            scwin.addToHistory("delete_branch", parts[1], branchName, "실패");
        });
    } catch (e) {
        scwin.setLoading(false);
    }
};

// OAuth 팝업 닫기 액션
scwin.oauthPopup_closeAction = function () {
    setTimeout(function () {
        scwin.checkAuthenticationStatus();
    }, 1000);
};


// 현재 프로젝트에 연결된 저장소 확인 (프로젝트 ID 기반)
scwin.checkCurrentRepository = function () {
    try {
        // 현재 프로젝트 ID 가져오기
        var projectId = scwin.getCurrentProjectId();
        if (!projectId) {
            scwin.loadConnectedRepositories();
            return;
        }

        // 프로젝트의 연결된 저장소 조회
        $.ajax({
            url: "/InsWebApp/github/project/currentRepository.pwkjson",
            type: "GET",
            dataType: "json",
            data: {
                projectId: projectId
            },
            success: function (result) {

                if (result && result.success) {
                    if (result.hasRepository && result.repository) {

                        // 저장소 정보를 전역변수에 저장
                        scwin.connectedRepository = result.repository;

                        // 바로 브랜치 관리 화면으로 이동
                        scwin.showBranchManagement(result.repository);
                    } else {
                        scwin.loadConnectedRepositories();
                    }
                } else {
                    scwin.loadConnectedRepositories();
                }
            },
            error: function (xhr, status, error) {
                scwin.loadConnectedRepositories();
            }
        });

    } catch (e) {
        scwin.loadConnectedRepositories();
    }
};

// 현재 프로젝트 ID 가져오기 헬퍼 함수
scwin.getCurrentProjectId = function () {
    try {
        // 여러 방법으로 프로젝트 ID 찾기
        var projectId = null;

        try {
            projectId = $p.getParameter("projectId") || $p.getParameter("project_id");
        } catch (e) { }

        // 현재 프로젝트 데이터에서 찾기
        if (!projectId && scwin.currentProjectData) {
            projectId = scwin.currentProjectData.projectId;
        }

        // 데이터맵에서 찾기
        if (!projectId) {
            try {
                projectId = dm_github_form.get("projectId");
            } catch (e) { }
        }
        return projectId;

    } catch (e) {
        return ""; // 기본값
    }
};
